#!/usr/bin/env python3
import owiener
from Crypto.Util.number import long_to_bytes
def rol(val, r, width):
    r %= width
    mask = (1 << width) - 1
    return ((val << r) | (val >> (width - r))) & mask

def ror(val, r, width):
    r %= width
    mask = (1 << width) - 1
    return ((val >> r) | (val << (width - r))) & mask
