WIDTH = 1024


c = rol(c, 7, WIDTH)
N = ror(N, 3, WIDTH)
e = rol(e, 4, WIDTH)
#--------Wiener's attack--------#

d = owiener.attack(e, N)

if d:
    m = pow(c, d, N)
    flag = long_to_bytes(m).decode()
    print(flag)
else:
    print("Wiener's Attack failed.")
